import { writeStdoutAsync } from "../../src/platform/index.js";
import { getStdinReader } from "../../src/platform/index.js";
export function startStdioJsonRpc(options) {
    const decoder = new TextDecoder();
    const encoder = new TextEncoder();
    const stdinReader = getStdinReader();
    const writeResponse = async (response) => {
        await writeStdoutAsync(encoder.encode(`${JSON.stringify(response)}\n`));
    };
    const readLoop = async () => {
        let buffer = "";
        while (options.isRunning()) {
            try {
                const { value, done } = await stdinReader.read();
                if (done)
                    break;
                if (!value)
                    continue;
                buffer += decoder.decode(value, { stream: true });
                while (true) {
                    const newlineIndex = buffer.indexOf("\n");
                    if (newlineIndex === -1)
                        break;
                    const line = buffer.slice(0, newlineIndex).trim();
                    buffer = buffer.slice(newlineIndex + 1);
                    if (!line)
                        continue;
                    let payload;
                    try {
                        payload = JSON.parse(line);
                    }
                    catch (error) {
                        await writeResponse(options.toParseErrorResponse(error));
                        continue;
                    }
                    let request;
                    try {
                        request = options.parseRequest(payload);
                    }
                    catch (error) {
                        await writeResponse(options.toInvalidRequestResponse(error));
                        continue;
                    }
                    const notification = options.isNotification(request);
                    try {
                        const response = await options.handleRequest(request);
                        if (!notification)
                            await writeResponse(response);
                    }
                    catch (error) {
                        if (!notification)
                            await writeResponse(options.toErrorResponse(error, request));
                    }
                }
            }
            catch {
                break;
            }
        }
    };
    void readLoop();
    return stdinReader;
}
